INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7001, "キャル", "たまには\n協力するのもいいんじゃない？\nあたしも手を貸してあげる", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 7, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7002, "コッコロ", "多くの方と協力して\n戦えるようです\n主さまなら、さぞ\nご活躍なさることでしょう", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 7, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 7003, "ペコリーヌ", "たくさんの人と一緒に\n協力バトルです！\nがんばりましょう☆", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 7, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10001, "ペコリーヌ", "ジュエルを食べ物…\nいえ、貴重品と交換できます！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 10, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10002, "キャル", "ジュエルはよく考えて\n使うことね\n無駄遣い厳禁！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 10, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 10003, "コッコロ", "主さまのジュエルで\n貴重な品々を購入できます\nですが、無駄遣いは\n『めっ』でございますよ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 10, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 10004, "シェフィ", "ジュエルがあれば\n貴重品と交換できるみたい\n大事に使いましょうね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 10, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 12001, "ペコリーヌ", "特定の条件を達成すると\n報酬がもらえますよ！\nがんばりましょう♪　", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 12, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13001, "キャル", "思い出が詰まってるって\nいろいろあったけど\n振り返るのもいいんじゃない？", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 13, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13002, "コッコロ", "主さまとの楽しい日々…\nこちらで何度でも\n思い返しましょう♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 13, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 13003, "シェフィ", "みんなとの大切な思い出が\nたくさん詰まってるのね\n一緒に振り返って、\n心に刻みたいわ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 13, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 13004, "ペコリーヌ", "女の子との思い出が\nたくさん見られますよ！\nヒューヒュー♪\nモテモテですねー☆", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 13, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14001, "コッコロ", "育成に必要なアイテムが\n獲得できるクエストです\nわたくし、主さまのために、\n強くなりますよ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 14, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 14002, "シェフィ", "このクエストを攻略すると、\nアイテムが手に入るらしいわ。\nもっと強くなるために、\n一生懸命がんばるわね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 14, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14003, "ペコリーヌ", "このクエストを攻略すれば、\nアイテムがもらえますよ\nたくさん集めて、どんどん\n強くなっちゃいましょう！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 14, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 14004, "キャル", "クエストを攻略すると、\nアイテムが手に入るんだって\nもらえるものは、\nもらっておきましょ！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 14, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 15001, "コッコロ", "主さま、旅の準備を整えて\nより充実した冒険をいたし\nましょう", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -470.0, 0, "2015/12/17 15:00:00", 1, 15, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 16001, "シェフィ", "ねぇ…クランに加入してみない？\n一人も楽しいけど、みんなと\n一緒も賑やかでいいと思うの", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 16, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16002, "ペコリーヌ", "クランに加入してみませんか？\nみんなといっしょに冒険した方が、\n楽しいですよ！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 16, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16003, "キャル", "クランに入れるらしいわよ\nせっかくだから入ってみたら？\nけっこう楽しいみたいよ♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 16, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 16004, "コッコロ", "こちらでクランに加入できます\n素敵なクランがたくさんあって、\n目移りしてしまいますね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 16, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 17002, "コッコロ", " こちらではクランバトルに\n 参加された仲間のみなさんの\n 活躍を振り返ることができます", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 17, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 17004, "キャル", "模擬戦の戦績もアンタが\n気に入ったものがあれば\n記録しておけるのね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 25, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 17005, "コッコロ", "主さま、今回のクランバトルでの\nご活躍が記録されています\nバトルの参考にいたしましょう", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 25, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 17006, "シェフィ", "今回のクランバトルの調子は\nどうかしら？\n戦績を見れば、次のバトルに\n活かせるかもしれないわ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 25, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 17007, "ペコリーヌ", "今回のクランバトルでの戦績を\nおさらいできますよ！\n私にも見せてください☆", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 25, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 18001, "カリン", "ようこそ！\nこちらでは、\nギルドハウスで流れる音楽の\n変更や購入が出来ますよ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 18, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 18002, "カリン", "ＢＧＭの変更や購入は、こちらから\nできますよ\n素敵な音楽を、たくさんご用意\nいたしました！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 2, 18, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 19001, "カリン", "ギルドハウスの\nＢＧＭを変更できますよ\nあなたの好きな曲、\n私にも聴かせてくださいね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -470.0, 0, "2015/12/17 15:00:00", 3, 19, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 19002, "カリン", "こちらでは、ＢＧＭの変更が\nできますよ\nどんな曲に変更しますか？\nふふふ、私も楽しみです♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -470.0, 0, "2015/12/17 15:00:00", 4, 19, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 20001, "カリン", "こちらでは、ＢＧＭを購入\nすることができますよ\n試聴することもできるので、\nじっくり選んでくださいね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -470.0, 0, "2015/12/17 15:00:00", 5, 20, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 20002, "カリン", "いらっしゃいませ！\nＢＧＭの購入はこちらです\n素敵な曲がたくさんあって、\n目移りしちゃいますね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -470.0, 0, "2015/12/17 15:00:00", 6, 20, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21001, "キャル", "ここで手に入れたアイテムで\n専用装備を作成できるみたいね\nアイテムが集まったら\nさっそく作ってみましょ！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 21, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21002, "コッコロ", "攻略すると珍しいアイテムが\n手に入りますよ\nこのアイテムで専用装備を\n作成できるようです", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 21, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 21003, "シェフィ", "専用装備が欲しいなら\nこのクエストに挑戦するといいわ\n集めた素材でもっともっと\n強くなりましょう", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 21, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 21004, "ペコリーヌ", "専用装備の作成に必要な\nアイテムを獲得できますよ\nたくさん集めてどんどん\n強くなりましょう！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 21, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 22001, "カリン", "投票はこちらです\nあなたが応援したい女の子に\n思いを込めた一票を\nお願いします！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -430.0, 0, "2015/12/17 15:00:00", 1, 22, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 22002, "カリン", "ようこそ！\nあなたが思いを寄せるのは\nどの女の子ですか？\n応援してあげてくださいね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -430.0, 0, "2015/12/17 15:00:00", 2, 22, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 23001, "カリン", "たくさんの投票、\nありがとうございました\n結果発表を楽しみに\n待っていてくださいね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -430.0, 0, "2015/12/17 15:00:00", 3, 23, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 23002, "カリン", "ただ今、人気投票の\n集計中です\n結果が出るまでもう少しだけ\nお待ちくださいね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -430.0, 0, "2015/12/17 15:00:00", 4, 23, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24001, "エリコ（バレンタイン）", "あなた様が手伝ってくださった\nチョコレートケーキ\n美味しくないはずがありませんわ", "2030/12/17 14:59:59", 8.0, 2, 4.08, 0, -385.0, 10011, "2019/01/31 12:00:00", 1, 24, 109001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24002, "エリコ（バレンタイン）", "このような失敗、あなた様が\nするはずありません\nもう一度挑戦してみましょう", "2030/12/17 14:59:59", 8.0, 2, 5.0, 0, -385.0, 10011, "2019/01/31 12:00:00", 2, 24, 109001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24003, "エリコ（バレンタイン）", "あなた様のために\n作っているケーキを\nあなた様に手伝っていただく……\nことになるなんて……クスクス", "2030/12/17 14:59:59", 8.0, 2, 10.11, 0, -385.0, 10011, "2019/01/31 12:00:00", 3, 24, 109001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24004, "エリコ（バレンタイン）", "あまり気に病む必要はありませんわ\nこれからは私がたっぷりと\n時間をかけて教えて差し上げますから", "2030/12/17 14:59:59", 8.0, 2, 4.0, 0, -385.0, 10011, "2019/01/31 12:00:00", 4, 24, 109001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24005, "エリコ（バレンタイン）", "今回は調子が悪かった……のですか？\nあなた様が手伝ってくれたものなら\nわたしはどんなものでも……クスクス", "2030/12/17 14:59:59", 8.0, 2, 6.0, 0, -385.0, 10011, "2019/01/31 12:00:00", 5, 24, 109001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24006, "エリコ（バレンタイン）", "あなた様が手がけた\nチョコレートケーキは\n私にとっての宝物……\n侮辱する者は生かしておきませんわ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 6, 24, 109002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24007, "エリコ（バレンタイン）", "とても素晴らしい出来栄えですわ！\nあなた様にふさわしい\nチョコレートケーキができました", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 7, 24, 109002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24008, "エリコ（バレンタイン）", "私を手伝ってくれたあなた様は\nすでに私の虜……\n甘い世界に誘って差し上げますわ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 8, 24, 109002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24009, "エリコ（バレンタイン）", "あなた様の愛情\nしかと受け止めました\nこれが……私たちの初めての\n共同作業ですわね……クスクス", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 9, 24, 109002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24010, "エリコ（バレンタイン）", "これは世界一の\nチョコレートケーキですわ\nだって、あなた様が腕によりをかけて\n作ってくださったんですもの", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 10, 24, 109002);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24011, "シズル（バレンタイン）", "上手にできなくて残念だった？\nでも、弟くんの気持ちが嬉しいな\nいつだってお姉ちゃんは\nそばにいるからね♪", "2030/12/17 14:59:59", 8.0, 2, 2.12, 0, -385.0, 10011, "2019/01/31 12:00:00", 1, 24, 109101);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 24012, "シズル（バレンタイン）", "うーん、弟くんには珍しく\n緊張しちゃったのかな？\nもう一度チャレンジしてみる？", "2030/12/17 14:59:59", 8.0, 2, 4.19, 0, -385.0, 10011, "2019/01/31 12:00:00", 2, 24, 109101);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 24013, "シズル（バレンタイン）", "お姉ちゃんのお手伝い、\nよくできました！\nあー、\nまだつまみ食いしちゃダメだぞ！", "2030/12/17 14:59:59", 8.0, 4, 2.3, 0, -385.0, 10011, "2019/01/31 12:00:00", 3, 24, 109101);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24014, "シズル（バレンタイン）", "見てみて！\nスポンジに綺麗な焼き目がついてるよ\nさっすが弟くんだね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 4, 24, 109102);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (5, 24015, "シズル（バレンタイン）", "まぁまぁ、落ち込まないで\n見た目は……個性的だけど、\n味は絶対美味しいはずだから！", "2030/12/17 14:59:59", 8.0, 2, 5.23, 0, -385.0, 10011, "2019/01/31 12:00:00", 5, 24, 109101);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24016, "シズル（バレンタイン）", "弟くんみたいな\n可愛いケーキができたよ！\n早く食べてみたいでしょ♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 6, 24, 109102);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24017, "シズル（バレンタイン）", "あれれ？　弟くん、指に\nチョコレートがくっついてるよ？\nお姉ちゃんが舐めてあげるね、\nはぁむ！", "2030/12/17 14:59:59", 8.0, 2, 5.01, 0, -385.0, 10011, "2019/01/31 12:00:00", 7, 24, 109101);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24018, "シズル（バレンタイン）", "なかなか上手にできたんじゃない？\nでも弟くんはまだまだできる子！\nお姉ちゃん、信じてるからね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 8, 24, 109102);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24019, "シズル（バレンタイン）", "わぁ～、\nとっても美味しそうにできたね！\n弟くん手慣れてたから\nお姉ちゃん安心して任せられちゃった！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 9, 24, 109102);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 24020, "シズル（バレンタイン）", "や～ん、弟くんが手伝ってくれた\nチョコレートケーキ！\nすっごく美味しそうにできたね♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, 0.0, 10011, "2019/01/31 12:00:00", 10, 24, 109102);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 26001, "シェフィ", "ここから先は神聖な場所みたい\nどんなお宝が眠っているのか、\n今から探索するのが楽しみね♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 26, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 26002, "ペコリーヌ", "ここから先は神聖な場所\nみたいです！\nどんなお宝が手に入るか\n楽しみですね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 26, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 26003, "キャル", "この先は神聖な場所みたい。\n手に入るお宝も並じゃないけど\n気を付けていかないと\n痛い目にあうわよ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 26, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 26004, "コッコロ", "ここから先は神聖な場所\nでございます。\n気を引き締めてお宝の\n調査探索に参りましょう", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 26, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 27001, "シェフィ", "ここにさらなる力を得るための\nアイテムが眠っている…って\nみんな言ってるわ。ふふっ、\nそれじゃあ挑戦してみましょうか", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 27, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 27002, "ペコリーヌ", "ここにさらなる力を得るための\nアイテムが眠っているみたい\nです！　どこから挑戦するか\n迷っちゃいますね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 27, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 27003, "キャル", "ここにさらなる力を得るための\nアイテムが眠っているみたい！\nどんどん挑戦して\n強くなっちゃいましょ！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 27, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 27004, "コッコロ", "こちらにさらなる力を得る\nためのアイテムが眠っている\nようです。主さま、どこから\n挑戦いたしましょう。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 27, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 28001, "カリン", "ようこそ！\n皆さんの素敵な出会いを\nギルド管理協会が\nお手伝いします！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2019/09/24 15:00:00", 1, 28, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 28002, "カリン", "ギルド管理協会です\nフレンドに関しては\nこちらでご確認ください", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2019/09/24 15:00:00", 2, 28, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 29001, "カリン", "こちらがフレンドの\n皆さんです\n素敵な関係を\n築いてくださいね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/09/24 15:00:00", 3, 29, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 29002, "カリン", "こちらの一覧で\nフレンドのプロフィールを\n確認できますよ", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/09/24 15:00:00", 4, 29, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 30001, "カリン", "フレンド管理は\nこちらになります\n新しいフレンドとの出会いを\n楽しんでくださいね！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/09/24 15:00:00", 5, 30, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 30002, "カリン", "フレンドの申請や\n承認ができますよ\nどうぞ、良き交流を！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/09/24 15:00:00", 6, 30, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 31001, "カリン", "バトルをして力比べを\nしてみましょう！\n実力が試されますね、\n頑張ってください！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/10/31 12:00:00", 7, 31, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 31002, "カリン", "気になるパーティと\nバトルをしてみましょう！\nどちらが勝利するのか、\n私も楽しみにしていますね", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/10/31 12:00:00", 8, 31, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 32001, "カリン", "ルーキーの皆さんのために\n特別なミッションを\nご用意いたしました！\nぜひ、挑戦してください！", "2020/01/04 4:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/12/20 5:00:00", 1, 32, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 32002, "カリン", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2020/01/04 4:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/12/20 5:00:00", 2, 32, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 33001, "カリン", "フレンドになって\n初心者の方を応援しましょう！\n素敵な報酬が待っていますよ！", "2020/01/04 4:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/12/20 5:00:00", 3, 33, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 33002, "カリン", "期間限定のキャンペーンを\n開催中です！\nミッションにチャレンジ\nしましょう！", "2020/01/04 4:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2019/12/20 5:00:00", 4, 33, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 34001, "カリン", "お疲れ様でした！\nミッションの報酬の受け取りは\nこちらからできますよ！", "2020/01/10 11:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2020/01/04 5:00:00", 5, 34, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 34002, "カリン", "ミッション報酬の受け取りは\nこちら！\n受け取り漏れの無いように\n気を付けてくださいね！", "2020/01/10 11:59:59", 0.0, 1, 0.0, 0, -409.0, 0, "2020/01/04 5:00:00", 6, 34, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 38001, "ペコリーヌ", "過去のストーリーイベントを\n楽しめちゃいますよ！\n遊んだことのないものがあれば\n一緒にやってみましょう♪", "2030/12/17 14:59:59", 0.0, 2, 5.3, 0, -458.0, 0, "2015/12/17 15:00:00", 1, 38, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 38002, "ペコリーヌ", "これまでのイベントで登場した\n限定キャラを仲間にできたり\nメモリーピースが手に入る\nみたいですよ。やばいですね☆", "2030/12/17 14:59:59", 0.0, 2, 6.5, 0, -458.0, 0, "2015/12/17 15:00:00", 2, 38, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (3, 39005, "ペコリーヌ", "", "2020/04/08 23:59:59", 9999.0, 3, 0.0, 0, 9999.0, 0, "2020/04/01", 0, 39, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 40001, "カリン", "これまでに出題された\n問題を振り返ることが\nできますよ\n復習は大切です♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -430.0, 0, "2015/12/17 15:00:00", 2, 40, 190801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 41001, "シェフィ", "ここでは腕試しが\nできるんですって。\n自分の実力を測るのに、\nちょうどよさそうね。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -363.0, 0, "2015/12/17 15:00:00", 1, 41, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 41002, "ペコリーヌ", "ここで腕試しを\nしていきましょう！\n全力全開、\nがんばっちゃいますよ～！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 41, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 41003, "キャル", "ここで腕試しが\nできるみたいね。\n試してみるのも\nいいんじゃない？", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 41, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 41004, "コッコロ", "腕試しができるようです。\nここで練習を重ね、実戦に\n活かしてまいりましょう。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 41, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 42001, "コッコロ", "訓練の成果に応じて、\n報酬がもらえるそうです。\n共に励んでいきましょう。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 42, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 42002, "シェフィ", "目標を達成すれば、\n報酬がもらえるみたい。\n頑張り甲斐があるわね。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 2104010, -416.5, 0, "2015/12/17 15:00:00", 1, 42, 106401);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 42003, "ペコリーヌ", "腕試しをがんばれば、\n報酬がもらえますよ。\n挑戦していきましょう☆", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 42, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 42004, "キャル", "ミッションを達成すると、\n報酬が出るんですって。\n一緒にやってみましょ！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 42, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43001, "ペコリーヌ", "ここからアリーナに\n挑戦できますよ！\n編成を工夫してライバルに\n挑んじゃいましょう！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 43, 105801);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43002, "コッコロ", "こちらからアリーナに\n挑戦することができます。\n主さまらしい編成で\nライバルに挑みましょう。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 43, 105901);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43003, "キャル", "ここからアリーナに\n挑戦できるわよ！\nしっかり編成を考えて\nライバルに挑みなさい！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -363.0, 0, "2015/12/17 15:00:00", 1, 43, 106001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43004, "アメス", "ミッションをクリアすると報酬が\n受け取れるわ。ジャンジャン\nクリアしてバリバリ強化して\nあげなさい♪", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 44, 123001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43005, "アメス", "ぼんやりしてる場合じゃないわ。\n早くミッションをクリアして\n報酬を受け取ってきなさい！", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 2, 44, 123001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 43006, "アメス", "ちょっとあんた、報酬が\n受け取れるじゃない！\n忘れずにチェックなさい。\nアメス様との約束よ？", "2030/12/17 14:59:59", 0.0, 2, 5.79, 0, -416.5, 0, "2015/12/17 15:00:00", 3, 45, 123001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (1, 46001, "アメス", "はい、お疲れさま。\nここではマスタリーチケットを\n使って、マスタリー強化素材を\n手に入れることができるわよ。", "2030/12/17 14:59:59", 0.0, 1, 0.0, 0, -371.5, 0, "2015/12/17 15:00:00", 1, 46, 123001);
INSERT INTO `v1_afada165da633f60da92ee35528ab3818cbb002ed76e67c7aad8da57078d3fff` VALUES (2, 47001, "シズル", "呼ばれて飛び出てお姉ちゃんだよ♪\nたとえ火の中、水の中、迷宮の中っ\nこのダンジョンを踏破できるよう\n弟くんを応援してあげるからねっ♪", "2030/12/17 14:59:59", 0.0, 2, 0.0, 0, -416.5, 0, "2015/12/17 15:00:00", 1, 47, 104901);
